<?php
defined( 'ABSPATH' ) || exit;
final class EduFlow_Report_Service {
	public static function range($preset='last_7_days',$from='',$to=''){$tz=new DateTimeZone(EduFlow_Settings::get_all()['timezone']??'UTC');$today=new DateTimeImmutable('today',$tz);switch(sanitize_key($preset)){case'today':$start=$end=$today;break;case'yesterday':$start=$end=$today->modify('-1 day');break;case'this_month':$start=$today->modify('first day of this month');$end=$today;break;case'last_month':$start=$today->modify('first day of last month');$end=$today->modify('last day of last month');break;case'custom':$start=DateTimeImmutable::createFromFormat('!Y-m-d',sanitize_text_field($from),$tz);$end=DateTimeImmutable::createFromFormat('!Y-m-d',sanitize_text_field($to),$tz);if(!$start||!$end||$start>$end){return new WP_Error('invalid_report_range','Choose a valid report date range.');}break;default:$start=$today->modify('-6 days');$end=$today;}return array($start->format('Y-m-d'),$end->format('Y-m-d'));}
	public static function summary($from,$to,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$t=array('s'=>EduFlow_DB::table('students'),'ad'=>EduFlow_DB::table('admissions'),'a'=>EduFlow_DB::table('attendance'),'c'=>EduFlow_DB::table('classes'),'t'=>EduFlow_DB::table('teachers'),'d'=>EduFlow_DB::table('demo_bookings'),'ds'=>EduFlow_DB::table('demo_sessions'),'p'=>EduFlow_DB::table('payments'),'x'=>EduFlow_DB::table('access'),'h'=>EduFlow_DB::table('access_history'),'n'=>EduFlow_DB::table('notifications'));
		$q=static function($sql,...$args)use($wpdb){return (int)$wpdb->get_var($wpdb->prepare($sql,...$args));};
		return array('active_students'=>$q("SELECT COUNT(*) FROM {$t['s']} WHERE institute_id=%d AND student_status='active'",$institute_id),'expired_students'=>$q("SELECT COUNT(*) FROM {$t['x']} WHERE institute_id=%d AND access_status='expired'",$institute_id),'new_admissions'=>$q("SELECT COUNT(*) FROM {$t['ad']} WHERE institute_id=%d AND admission_date BETWEEN %s AND %s",$institute_id,$from,$to),'attendance_present'=>$q("SELECT COUNT(*) FROM {$t['a']} a INNER JOIN {$t['c']} c ON c.id=a.lecture_id AND c.institute_id=a.institute_id WHERE a.institute_id=%d AND c.class_date BETWEEN %s AND %s AND a.attendance_status IN ('present','late')",$institute_id,$from,$to),'attendance_absent'=>$q("SELECT COUNT(*) FROM {$t['a']} a INNER JOIN {$t['c']} c ON c.id=a.lecture_id AND c.institute_id=a.institute_id WHERE a.institute_id=%d AND c.class_date BETWEEN %s AND %s AND a.attendance_status='absent'",$institute_id,$from,$to),'classes_scheduled'=>$q("SELECT COUNT(*) FROM {$t['c']} WHERE institute_id=%d AND class_date BETWEEN %s AND %s AND class_status IN ('scheduled','rescheduled')",$institute_id,$from,$to),'classes_completed'=>$q("SELECT COUNT(*) FROM {$t['c']} WHERE institute_id=%d AND class_date BETWEEN %s AND %s AND class_status='completed'",$institute_id,$from,$to),'classes_cancelled'=>$q("SELECT COUNT(*) FROM {$t['c']} WHERE institute_id=%d AND class_date BETWEEN %s AND %s AND class_status='cancelled'",$institute_id,$from,$to),'demo_bookings'=>$q("SELECT COUNT(*) FROM {$t['d']} b INNER JOIN {$t['ds']} d ON d.id=b.session_id AND d.institute_id=b.institute_id WHERE b.institute_id=%d AND d.demo_date BETWEEN %s AND %s",$institute_id,$from,$to),'demo_attended'=>$q("SELECT COUNT(*) FROM {$t['d']} b INNER JOIN {$t['ds']} d ON d.id=b.session_id AND d.institute_id=b.institute_id WHERE b.institute_id=%d AND d.demo_date BETWEEN %s AND %s AND b.attendance_status IN ('present','late')",$institute_id,$from,$to),'demo_no_show'=>$q("SELECT COUNT(*) FROM {$t['d']} b INNER JOIN {$t['ds']} d ON d.id=b.session_id AND d.institute_id=b.institute_id WHERE b.institute_id=%d AND d.demo_date BETWEEN %s AND %s AND b.attendance_status='no_show'",$institute_id,$from,$to),'demo_converted'=>$q("SELECT COUNT(*) FROM {$t['d']} b INNER JOIN {$t['ds']} d ON d.id=b.session_id AND d.institute_id=b.institute_id WHERE b.institute_id=%d AND d.demo_date BETWEEN %s AND %s AND b.conversion_status='converted'",$institute_id,$from,$to),'verified_payments'=>$q("SELECT COUNT(*) FROM {$t['p']} WHERE institute_id=%d AND payment_date BETWEEN %s AND %s AND verification_status='verified'",$institute_id,$from,$to),'pending_payments'=>$q("SELECT COUNT(*) FROM {$t['p']} WHERE institute_id=%d AND payment_date BETWEEN %s AND %s AND verification_status='pending'",$institute_id,$from,$to),'active_access'=>$q("SELECT COUNT(*) FROM {$t['x']} WHERE institute_id=%d AND access_status='active'",$institute_id),'renewals'=>$q("SELECT COUNT(*) FROM {$t['h']} WHERE institute_id=%d AND created_at BETWEEN %s AND %s AND change_type='extension'",$institute_id,$from.' 00:00:00',$to.' 23:59:59'),'failed_notifications'=>$q("SELECT COUNT(*) FROM {$t['n']} WHERE institute_id=%d AND notification_status='failed'",$institute_id));}
	public static function teacher_workload($from,$to,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$teachers=EduFlow_DB::table('teachers');$classes=EduFlow_DB::table('classes');return $wpdb->get_results($wpdb->prepare("SELECT t.canonical_id,t.name,COUNT(c.id) assigned,SUM(c.class_status='completed') completed,SUM(c.class_status='cancelled') cancelled,SUM(c.class_status IN ('scheduled','rescheduled','missed')) not_completed,SUM(TIMESTAMPDIFF(MINUTE,c.start_datetime,c.end_datetime)) scheduled_minutes,SUM(IF(c.class_status='completed',TIMESTAMPDIFF(MINUTE,c.start_datetime,c.end_datetime),0)) completed_minutes,SUM(c.class_type='batch') batch_classes,SUM(c.class_type='1-to-1') one_to_one_classes,SUM(c.class_type='demo') demo_sessions FROM $teachers t LEFT JOIN $classes c ON c.teacher_id=t.id AND c.institute_id=t.institute_id AND c.class_date BETWEEN %s AND %s WHERE t.institute_id=%d GROUP BY t.id ORDER BY t.name",$from,$to,$institute_id),ARRAY_A);}
	public static function breakdowns($from,$to,$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$s=EduFlow_DB::table('students');$b=EduFlow_DB::table('batches');$a=EduFlow_DB::table('attendance');$c=EduFlow_DB::table('classes');return array(
		'course_students'=>$wpdb->get_results($wpdb->prepare("SELECT course,COUNT(*) students FROM $s WHERE institute_id=%d AND student_status='active' GROUP BY course ORDER BY students DESC",$institute_id),ARRAY_A),
		'batch_students'=>$wpdb->get_results($wpdb->prepare("SELECT COALESCE(b.batch_name,'Unassigned') batch_name,COUNT(s.id) students FROM $s s LEFT JOIN $b b ON b.id=s.batch_id AND b.institute_id=s.institute_id WHERE s.institute_id=%d AND s.student_status='active' GROUP BY s.batch_id,b.batch_name ORDER BY students DESC",$institute_id),ARRAY_A),
		'daily_attendance'=>$wpdb->get_results($wpdb->prepare("SELECT c.class_date,SUM(a.attendance_status IN ('present','late')) attended,SUM(a.attendance_status='absent') absent,ROUND(100*SUM(a.attendance_status IN ('present','late'))/NULLIF(SUM(a.attendance_status IN ('present','late','absent','excused')),0),2) percentage FROM $a a INNER JOIN $c c ON c.id=a.lecture_id AND c.institute_id=a.institute_id WHERE a.institute_id=%d AND c.class_date BETWEEN %s AND %s GROUP BY c.class_date ORDER BY c.class_date",$institute_id,$from,$to),ARRAY_A),
		'batch_attendance'=>$wpdb->get_results($wpdb->prepare("SELECT b.batch_name,SUM(a.attendance_status IN ('present','late')) attended,SUM(a.attendance_status='absent') absent,ROUND(100*SUM(a.attendance_status IN ('present','late'))/NULLIF(SUM(a.attendance_status IN ('present','late','absent','excused')),0),2) percentage FROM $a a INNER JOIN $c c ON c.id=a.lecture_id AND c.institute_id=a.institute_id INNER JOIN $b b ON b.id=a.batch_id AND b.institute_id=a.institute_id WHERE a.institute_id=%d AND c.class_date BETWEEN %s AND %s GROUP BY b.id,b.batch_name ORDER BY b.batch_name",$institute_id,$from,$to),ARRAY_A),
		'class_types'=>$wpdb->get_results($wpdb->prepare("SELECT class_type,class_status,COUNT(*) classes FROM $c WHERE institute_id=%d AND class_date BETWEEN %s AND %s GROUP BY class_type,class_status ORDER BY class_type,class_status",$institute_id,$from,$to),ARRAY_A),
	);}
	public static function attendance_rows($from,$to,$institute_id=0,$limit=100,$offset=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$a=EduFlow_DB::table('attendance');$c=EduFlow_DB::table('classes');$s=EduFlow_DB::table('students');$b=EduFlow_DB::table('batches');$t=EduFlow_DB::table('teachers');return $wpdb->get_results($wpdb->prepare("SELECT c.id lecture_db_id,a.canonical_id,c.canonical_id lecture_id,c.class_date,s.canonical_id student_id,s.name student,b.batch_name,t.name teacher,c.class_type,a.attendance_status,a.minutes_attended,a.marked_at FROM $a a INNER JOIN $c c ON c.id=a.lecture_id AND c.institute_id=a.institute_id LEFT JOIN $s s ON s.id=a.student_id AND s.institute_id=a.institute_id LEFT JOIN $b b ON b.id=a.batch_id AND b.institute_id=a.institute_id INNER JOIN $t t ON t.id=c.teacher_id AND t.institute_id=c.institute_id WHERE a.institute_id=%d AND c.class_date BETWEEN %s AND %s ORDER BY c.class_date DESC,a.id DESC LIMIT %d OFFSET %d",$institute_id,$from,$to,min(1000,absint($limit)),absint($offset)),ARRAY_A);}
}
